cat > tests/services/zz-tmp-change-lead.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as projectRepo from "@/server/repositories/project-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectService from "@/server/services/project-service";
import { can, ROLE_MATRIX } from "@/lib/permissions";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("smoke", async () => {
  const t = await createTenant("acme");
  const o = await createTenant("other");
  const input = { orgId: t.org.id, projectId: t.project.id };
  expect(ROLE_MATRIX["project:change_lead"]).toBe("admin");
  await expect(projectService.changeProjectLead(t.actors.member, { ...input, leadId: t.userIds.member })).rejects.toMatchObject({ name: "PermissionDeniedError" });
  await expect(projectService.changeProjectLead(t.actors.admin, { ...input, leadId: t.userIds.viewer })).rejects.toMatchObject({ name: "PermissionDeniedError" });
  await expect(projectService.changeProjectLead(t.actors.admin, { ...input, leadId: o.userIds.admin })).rejects.toMatchObject({ name: "NotFoundError" });
  await expect(projectService.changeProjectLead(t.actors.admin, { orgId: o.org.id, projectId: o.project.id, leadId: null })).rejects.toMatchObject({ name: "TenantScopeError" });
  await expect(projectService.changeProjectLead(t.actors.admin, { orgId: t.org.id, projectId: o.project.id, leadId: null })).rejects.toMatchObject({ name: "NotFoundError" });
  const p = await projectService.changeProjectLead(t.actors.admin, { ...input, leadId: t.userIds.member });
  expect(p.leadId).toBe(t.userIds.member);
  // member is now lead -> can change lead
  expect(can(t.actors.member, "project:change_lead", { kind: "project", orgId: t.org.id, projectId: p.id, visibility: p.visibility, leadId: p.leadId })).toBe(true);
  const p2 = await projectService.changeProjectLead(t.actors.member, { ...input, leadId: null });
  expect(p2.leadId).toBeNull();
  const m = await memberRepo.findMember(t.org.id, t.userIds.admin);
  await memberRepo.archiveMember(t.org.id, m!.id);
  await expect(projectService.changeProjectLead(t.actors.owner, { ...input, leadId: t.userIds.admin })).rejects.toMatchObject({ name: "NotFoundError" });
  await projectRepo.archiveProject(t.org.id, t.project.id);
  await expect(projectService.changeProjectLead(t.actors.owner, { ...input, leadId: t.userIds.member })).rejects.toMatchObject({ name: "AlreadyArchivedError" });
  expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.leadId).toBeNull();
});
EOF
npx vitest run tests/services/zz-tmp-change-lead.test.ts 2>&1 | tail -15; rm tests/services/zz-tmp-change-lead.test.ts

